<?php
defined('ABSPATH') || exit;
class SMF_Courier_Operations {
 public static function init(){add_action('admin_menu',array(__CLASS__,'menu'),35);add_action('admin_post_smf_save_courier_ops',array(__CLASS__,'save'));}
 public static function menu(){add_submenu_page('sync-meta-flow','Courier Operations','Courier Operations','manage_woocommerce','smf-courier-operations',array(__CLASS__,'page'));}
 private static function settings(){return array('default_provider'=>sanitize_key((string)get_option('smf_courier_provider','generic')),'risk_window'=>max(1,min(365,absint(get_option('smf_courier_risk_window',90)))),'processing_sla'=>max(1,min(1440,absint(get_option('smf_courier_processing_sla',15)))),'delivery_sla'=>max(1,min(720,absint(get_option('smf_courier_delivery_sla',72))));}
 private static function status_key($s){$s=strtolower(sanitize_key((string)$s));if(in_array($s,array('completed','smf-delivered'),true))return'delivered';if(in_array($s,array('smf-returned','refunded'),true))return'returned';if(in_array($s,array('cancelled','failed'),true))return'cancelled';if($s==='smf-shipped')return'shipped';if($s==='smf-confirmed')return'confirmed';return'other';}
 public static function risk_score($stats){$o=max(0,(int)($stats['orders']??0));$d=max(0,(int)($stats['delivered']??0));$r=max(0,(int)($stats['returned']??0));$c=max(0,(int)($stats['cancelled']??0));$score=50;if($o>0)$score=50+($d/$o)*40-($r/$o)*60-($c/$o)*30;$score=max(0,min(100,round($score)));return array('score'=>$score,'label'=>$score>=75?'LOW RISK':($score>=45?'MEDIUM RISK':'HIGH RISK'));}
 public static function customer_risk($order_id){$o=wc_get_order(absint($order_id));if(!$o)return array('score'=>0,'label'=>'Unknown','orders'=>0,'delivered'=>0,'returned'=>0,'cancelled'=>0);$email=sanitize_email($o->get_billing_email());$phone=preg_replace('/\D+/','',(string)$o->get_billing_phone());$window=self::settings()['risk_window'];$since=gmdate('Y-m-d H:i:s',time()-$window*DAY_IN_SECONDS);$a=array('limit'=>100,'return'=>'ids','exclude'=>array($o->get_id()),'date_created'=>'>='.$since);if($email)$a['billing_email']=$email;elseif($phone)$a['billing_phone']=$phone;else return array('score'=>0,'label'=>'Unknown','orders'=>0,'delivered'=>0,'returned'=>0,'cancelled'=>0);$ids=wc_get_orders($a);$st=array('orders'=>0,'delivered'=>0,'returned'=>0,'cancelled'=>0);foreach($ids as $id){$prev=wc_get_order($id);if(!$prev)continue;$st['orders']++;$k=self::status_key($prev->get_status());if($k==='delivered')$st['delivered']++;elseif($k==='returned')$st['returned']++;elseif($k==='cancelled')$st['cancelled']++;}$risk=self::risk_score($st);return array_merge($st,$risk);}
 public static function recommend_provider($o){$p=self::settings()['default_provider'];$r=self::customer_risk($o->get_id());$intel=self::provider_intelligence(30);if($p==='generic'&&!empty($intel)){$best=$intel[0];$p=$best['provider'];$reason='Best observed provider health score: '.$best['health_score'].'/100';}else{$reason=$p!=='generic'?'Configured default provider':($r['label']==='HIGH RISK'?'High-risk customer: review before dispatch':'No native provider selected');}return array('provider'=>$p,'risk'=>$r,'reason'=>$reason);}
 private static function orders_window($days){return wc_get_orders(array('limit'=>200,'type'=>'shop_order','date_created'=>'>='.gmdate('Y-m-d H:i:s',time()-$days*DAY_IN_SECONDS),'orderby'=>'date','order'=>'DESC','return'=>'objects'));}
 private static function provider_stats($days){global $wpdb;$t=$wpdb->prefix.'smf_courier_events';$since=gmdate('Y-m-d H:i:s',time()-$days*DAY_IN_SECONDS);$r=$wpdb->get_results($wpdb->prepare("SELECT provider,COUNT(*) events,SUM(result='processed') processed,SUM(result='failed') failed FROM $t WHERE received_at >= %s GROUP BY provider ORDER BY events DESC",$since),ARRAY_A);return$r?:array();}
 public static function provider_intelligence($days=30){global $wpdb;SMF_Courier_Timeline::ensure_table();$s=self::settings();$days=max(1,min(365,absint($days)));$since=gmdate('Y-m-d H:i:s',time()-$days*DAY_IN_SECONDS);$t=$wpdb->prefix.'smf_courier_events';$rows=$wpdb->get_results($wpdb->prepare("SELECT provider,COUNT(*) events,SUM(result='processed') processed,SUM(result='failed') failed,SUM(attempts>1) retried,AVG(CASE WHEN processed_at IS NOT NULL AND received_at IS NOT NULL THEN GREATEST(0,TIMESTAMPDIFF(SECOND,received_at,processed_at)) ELSE NULL END) processing_seconds,SUM(CASE WHEN processed_at IS NOT NULL AND received_at IS NOT NULL AND TIMESTAMPDIFF(MINUTE,received_at,processed_at)>%d THEN 1 ELSE 0 END) sla_breaches FROM $t WHERE received_at >= %s GROUP BY provider ORDER BY events DESC",$s['processing_sla'],$since),ARRAY_A);$out=array();foreach($rows?:array() as $r){$events=max(0,(int)$r['events']);$processed=max(0,(int)$r['processed']);$failed=max(0,(int)$r['failed']);$retried=max(0,(int)$r['retried']);$success=$events?($processed/$events)*100:100;$retry_rate=$events?($retried/$events)*100:0;$avg=(float)$r['processing_seconds'];$latency_score=$avg<=0?100:max(0,100-(($avg/($s['processing_sla']*60))*100));$failure_score=max(0,100-(($failed/max(1,$events))*100));$retry_score=max(0,100-(($retry_rate*2)));$sla_score=$events?max(0,100-(((int)$r['sla_breaches']/$events)*100)):100;$health=(int)round(($success*.35)+($latency_score*.25)+($retry_score*.20)+($sla_score*.20));$out[]=array('provider'=>(string)$r['provider'],'events'=>$events,'processed'=>$processed,'failed'=>$failed,'retried'=>$retried,'success_rate'=>round($success,1),'retry_rate'=>round($retry_rate,1),'avg_processing_seconds'=>round($avg,1),'sla_breaches'=>(int)$r['sla_breaches'],'health_score'=>max(0,min(100,$health)),'health_label'=>$health>=80?'HEALTHY':($health>=60?'WATCH':'DEGRADED'));}usort($out,function($a,$b){return $b['health_score']<=>$a['health_score'];});return$out;}
 public static function combined_risk($order_id){$risk=self::customer_risk($order_id);$provider=self::provider_intelligence(30);$p=$provider?$provider[0]:array('health_score'=>100,'provider'=>'generic');$combined=(int)round(($risk['score']*.55)+((int)$p['health_score']*.45));return array('customer_score'=>(int)$risk['score'],'customer_label'=>$risk['label'],'provider'=>$p['provider'],'courier_health'=>(int)$p['health_score'],'combined_score'=>$combined,'combined_label'=>$combined>=75?'LOW RISK':($combined>=50?'MEDIUM RISK':'HIGH RISK'));}
 private static function queue(){ $out=array();foreach(self::orders_window(30) as $o){$k=self::status_key($o->get_status());if(!in_array($k,array('confirmed','shipped'),true)||$o->get_meta('_smf_tracking_number'))continue;$risk=self::customer_risk($o->get_id());$rec=self::recommend_provider($o);$out[]=array('id'=>$o->get_id(),'date'=>$o->get_date_created()?$o->get_date_created()->date_i18n('Y-m-d H:i'):'','total'=>$o->get_total(),'status'=>$o->get_status(),'risk'=>$risk,'provider'=>$rec['provider'],'reason'=>$rec['reason']);}return$out;}
 public static function save(){if(!current_user_can('manage_woocommerce'))wp_die('Unauthorized');check_admin_referer('smf_save_courier_ops');update_option('smf_courier_risk_window',max(1,min(365,absint($_POST['risk_window']??90))),false);update_option('smf_courier_processing_sla',max(1,min(1440,absint($_POST['processing_sla']??15))),false);update_option('smf_courier_delivery_sla',max(1,min(720,absint($_POST['delivery_sla']??72))),false);wp_safe_redirect(admin_url('admin.php?page=smf-courier-operations&updated=1'));exit;}
 public static function page(){if(!current_user_can('manage_woocommerce'))return;$s=self::settings();$q=self::queue();$p=self::provider_stats($s['risk_window']);$intel7=self::provider_intelligence(7);$intel30=self::provider_intelligence(30);$intel90=self::provider_intelligence(90);?><div class="wrap smf-wrap smf-settings"><div class="smf-header"><div><h1>Courier Operations</h1><p>Dispatch queue, customer-risk signals, SLA monitoring and provider intelligence.</p></div><a class="button" href="<?php echo esc_url(admin_url('admin.php?page=sync-meta-flow'));?>">← Dashboard</a></div><div class="smf-panel"><h2>Risk & SLA policy</h2><form method="post" action="<?php echo esc_url(admin_url('admin-post.php'));?>"><input type="hidden" name="action" value="smf_save_courier_ops"><?php wp_nonce_field('smf_save_courier_ops');?><p><label>Risk history (days)<br><input class="small-text" type="number" min="1" max="365" name="risk_window" value="<?php echo esc_attr($s['risk_window']);?>"></label> <label>Processing SLA (minutes)<br><input class="small-text" type="number" min="1" max="1440" name="processing_sla" value="<?php echo esc_attr($s['processing_sla']);?>"></label> <label>Delivery SLA (hours)<br><input class="small-text" type="number" min="1" max="720" name="delivery_sla" value="<?php echo esc_attr($s['delivery_sla']);?>"></label></p><?php submit_button('Save Policy');?></form><p class="smf-muted">SLA values are merchant-configurable thresholds, not claims about a courier's contractual delivery promise. Provider recommendations remain advisory.</p></div><div class="smf-panel"><h2>Provider health · 7 / 30 / 90 days</h2><?php foreach(array(7=>$intel7,30=>$intel30,90=>$intel90) as $days=>$rows):?><h3><?php echo esc_html($days);?> days</h3><div class="smf-table-wrap"><table class="smf-table"><thead><tr><th>Provider</th><th>Events</th><th>Success</th><th>Retry</th><th>Avg processing</th><th>SLA breaches</th><th>Health</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="7">No courier events recorded.</td></tr><?php else:foreach($rows as $r):?><tr><td><?php echo esc_html(ucfirst($r['provider']));?></td><td><?php echo esc_html($r['events']);?></td><td><?php echo esc_html($r['success_rate']);?>%</td><td><?php echo esc_html($r['retry_rate']);?>%</td><td><?php echo esc_html($r['avg_processing_seconds']);?>s</td><td><?php echo esc_html($r['sla_breaches']);?></td><td><strong><?php echo esc_html($r['health_label']);?></strong> · <?php echo esc_html($r['health_score']);?>/100</td></tr><?php endforeach;endif;?></tbody></table></div><?php endforeach;?></div><div class="smf-panel"><h2>Dispatch queue <span class="smf-muted">(last 30 days)</span></h2><div class="smf-table-wrap"><table class="smf-table"><thead><tr><th>Order</th><th>Date</th><th>Total</th><th>Status</th><th>Risk</th><th>Provider</th><th>Reason</th></tr></thead><tbody><?php if(!$q):?><tr><td colspan="7">No confirmed/shipped orders are waiting for courier tracking.</td></tr><?php else:foreach($q as $r):?><tr><td><a href="<?php echo esc_url(admin_url('post.php?post='.$r['id'].'&action=edit'));?>">#<?php echo esc_html($r['id']);?></a></td><td><?php echo esc_html($r['date']);?></td><td><?php echo esc_html(number_format_i18n((float)$r['total'],2));?></td><td><?php echo esc_html(wc_get_order_status_name($r['status']));?></td><td><strong><?php echo esc_html($r['risk']['label']);?></strong> · <?php echo esc_html($r['risk']['score']);?>/100</td><td><?php echo esc_html(ucfirst($r['provider']));?></td><td><?php echo esc_html($r['reason']);?></td></tr><?php endforeach;endif;?></tbody></table></div></div><div class="smf-panel"><h2>Legacy webhook performance</h2><div class="smf-table-wrap"><table class="smf-table"><thead><tr><th>Provider</th><th>Events</th><th>Processed</th><th>Failed</th></tr></thead><tbody><?php if(!$p):?><tr><td colspan="4">No courier events recorded in this window.</td></tr><?php else:foreach($p as $r):?><tr><td><?php echo esc_html(ucfirst($r['provider']));?></td><td><?php echo esc_html($r['events']);?></td><td><?php echo esc_html($r['processed']);?></td><td><?php echo esc_html($r['failed']);?></td></tr><?php endforeach;endif;?></tbody></table></div></div><div class="smf-panel"><h2>Routing policy</h2><p class="smf-muted">When no provider is configured, the highest-health observed provider is suggested from the last 30 days. Customer risk and courier health are combined for dispatch context; no automatic shipment is created.</p></div></div><?php }
}
